// ICSE 9 Mathematics ch05 — short-answer (2 and 3 marks) and long-answer (10 marks) items; continues questions.mjs.
// Method steps in the model answers are generated by lin.mjs from the computed system (multipliers, sums, denominators,
// back-substitution), so every number in them is the computed value; typed working lines are asserted at the
// verified solution; word problems are substituted back into the story.
import { Q, mk, r } from './lib.mjs';
import { F, Sys, sysFrom, elimSteps, substSteps, crossSteps, recipSys, W, holds, cleared, sameEq, evalTex, stepsMd } from './lin.mjs';

const d = (s) => `$${s}$`;
const J = (...p) => p.join('\n\n');
const L = (S, i) => d(S.tex(i));
const both = (S) => `${L(S, 1)} and ${L(S, 2)}`;
const fails = (env, line) => holds(env, line).length > 0;
const nums = (S) => [S.x.num, S.y.num];

// =============================================================== short answer, 2 marks
const S201 = sysFrom(7, 2, 5, -2, 4, 6);
const E201 = elimSteps(S201, 'y', 1);
Q('s201', mk.short({ marks: 2, stem: `Solve by the elimination method: ${both(S201)}.`, model: J('The coefficients of $y$ are $2$ and $-2$, so adding the equations eliminates $y$.', stepsMd(E201.rows)), sol: 'Add the equations, find $x$, then back-substitute.', scheme: [['Adding eliminates y: 12x = 48', 1], ['x = 4 and y = 6', 1]], d: 2, c: 'understanding', t: [1], time: 120 }), (C) => {
  C.assert(E201.op === 'add' && E201.k === 12 && E201.rhs === 48 && S201.x.eq(F(4)) && S201.y.eq(F(6)), '12x = 48; x = 4, y = 6');
  C.model([E201.k, E201.rhs, ...nums(S201)]);
});

const S202 = sysFrom(5, 1, 3, -2, 4, 2);
const U202 = substSteps(S202, 1, 'y');
Q('s202', mk.short({ marks: 2, stem: `Solve by the substitution method: ${both(S202)}.`, model: J('From the first equation, $y$ is the easiest variable to isolate (its coefficient is $1$).', stepsMd(U202.rows)), sol: 'Isolate $y$ in the first equation, substitute into the second, solve for $x$, then find $y$.', scheme: [['y = 22 - 5x substituted: 13x = 52', 1], ['x = 4 and y = 2', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => {
  C.assert(U202.K.eq(F(13)) && U202.C.eq(F(52)) && S202.x.eq(F(4)) && S202.y.eq(F(2)), '13x = 52; x = 4, y = 2');
  C.model([13, 52, ...nums(S202)]);
});

const S203 = sysFrom(3, -4, 2, 7, 5, -1);
const X203 = crossSteps(S203);
Q('s203', mk.short({ marks: 2, stem: `Use the cross-multiplication method to solve ${both(S203)}.`, model: J(r`First write the equations as $ax + by + c = 0$: the constants are $c_1 = -19$ and $c_2 = -3$.`, stepsMd(X203.rows)), sol: 'Write in standard form with c = minus the right-hand side, form the three denominators, then equate.', scheme: [['Standard form and denominators 145, -29, 29', 1], ['x = 5 and y = -1', 1]], d: 3, c: 'application', t: [3], time: 150 }), (C) => {
  C.assert(X203.c1 === -19 && X203.c2 === -3 && X203.Dx === 145 && X203.Dy === -29 && X203.D === 29 && S203.x.eq(F(5)) && S203.y.eq(F(-1)), 'denominators and solution');
  C.model([145, 29, 5, 1]);
});

const sq4 = [r`2(x - 3) = 3y + 1`, r`\dfrac{x}{4} - \dfrac{y}{3} = 1`];
const S204 = new Sys(2, -3, 7, 3, -4, 12);
Q('s204', mk.short({ marks: 2, stem: J(r`Write each equation in the form $ax + by = c$ with integer coefficients:`, `(a) ${d(sq4[0])}`, `(b) ${d(sq4[1])}`), model: r`(a) $2(x - 3) = 3y + 1$ gives $2x - 6 = 3y + 1$, so $2x - 3y = 7$.

(b) Multiply every term of $\dfrac{x}{4} - \dfrac{y}{3} = 1$ by $12$: $3x - 4y = 12$.`, sol: 'Expand brackets or multiply by the LCM of the denominators, then collect the unknowns on the left.', scheme: [['(a) 2x - 3y = 7', 1], ['(b) 3x - 4y = 12', 1]], d: 2, c: 'understanding', t: [1], time: 120 }), (C) => {
  const c = sq4.map((t) => cleared(t));
  C.assert(c[0].join() === '2,-3,7' && c[1].join() === '3,-4,12', 'cleared forms');
  C.assert(S204.x.eq(F(8)) && S204.y.eq(F(3)) && W(S204.env, [sq4[0], sq4[1], r`2x - 6 = 3y + 1`]), 'the original equations hold at the common solution (8, 3)');
  C.model([2, 3, 7, 12, 4]);
});

const R205 = recipSys(5, -2, 1, 3, 4, 11);
Q('s205', mk.short({ marks: 2, stem: r`In the pair $\dfrac{5}{x} - \dfrac{2}{y} = 1$ and $\dfrac{3}{x} + \dfrac{4}{y} = 11$, put $u = \dfrac{1}{x}$ and $v = \dfrac{1}{y}$. Write the pair as two linear equations in $u$ and $v$ and solve them for $u$ and $v$. (You need not find $x$ and $y$.)`, model: J(r`Since $\dfrac{5}{x} = 5u$, $\dfrac{2}{y} = 2v$, $\dfrac{3}{x} = 3u$ and $\dfrac{4}{y} = 4v$, the pair is $5u - 2v = 1$ and $3u + 4v = 11$.`, stepsMd(elimSteps(R205.S, 'v', 1).rows)), sol: 'Replace each reciprocal by u or v, then solve the linear pair.', scheme: [['5u - 2v = 1 and 3u + 4v = 11', 1], ['u = 1 and v = 2', 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => {
  C.assert(R205.S.x.eq(F(1)) && R205.S.y.eq(F(2)) && sameEq('5u - 2v = 1', R205.S.tex(1), 'u', 'v') && sameEq('3u + 4v = 11', R205.S.tex(2), 'u', 'v'), 'u = 1, v = 2');
  C.assert(R205.x.eq(F(1)) && R205.y.eq(F(1, 2)), 'x = 1, y = 1/2');
  C.model([5, 2, 3, 4, 11, 1]);
});

const S206 = new Sys(1, 1, 41, 2, -3, 7);
Q('s206', mk.short({ marks: 2, stem: r`Two numbers add up to $41$. Twice the larger number exceeds three times the smaller number by $7$. Frame two equations and find the numbers.`, model: r`Let the larger number be $x$ and the smaller $y$. Then $x + y = 41$ and $2x - 3y = 7$.

From the first, $x = 41 - y$, so $2(41 - y) - 3y = 7$, which gives $82 - 5y = 7$ and $y = 15$. Then $x = 41 - 15 = 26$.

The numbers are $26$ and $15$. Check: $2(26) - 3(15) = 52 - 45 = 7$.`, sol: 'Two unknowns, two conditions, substitute, then check in the story.', scheme: [['x + y = 41 and 2x - 3y = 7', 1], ['y = 15, x = 26, checked', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => {
  C.assert(S206.x.eq(F(26)) && S206.y.eq(F(15)) && 26 + 15 === 41 && 2 * 26 - 3 * 15 === 7, '26 and 15');
  C.assert(W(S206.env, [r`82 - 5y = 7`, r`2(41 - y) - 3y = 7`]), 'working');
  C.model([41, 7, 15, 26]);
});

const S207 = new Sys(2, 3, 1050, 1, 2, 600);
Q('s207', mk.short({ marks: 2, stem: r`At an imagined school store, $2$ sweaters and $3$ caps cost ₹$1050$, and $1$ sweater and $2$ caps cost ₹$600$. Find the price of one sweater and of one cap.`, model: r`Let a sweater cost ₹$s$ and a cap ₹$c$. Then $2s + 3c = 1050$ and $s + 2c = 600$.

Multiply the second by $2$: $2s + 4c = 1200$. Subtracting the first, $c = 150$. Then $s = 600 - 2(150) = 300$.

A sweater costs ₹$300$ and a cap ₹$150$. Check: $600 + 450 = 1050$.`, sol: 'Frame two equations, eliminate one price, then check.', scheme: [['2s + 3c = 1050 and s + 2c = 600', 1], ['c = 150 and s = 300', 1]], d: 2, c: 'application', t: [4], time: 120 }), (C) => {
  C.assert(S207.x.eq(F(300)) && S207.y.eq(F(150)) && 2 * 300 + 3 * 150 === 1050 && 300 + 2 * 150 === 600, 's = 300, c = 150');
  C.assert(W({ s: 300, c: 150 }, [r`2s + 4c = 1200`, r`s = 600 - 2(150)`]), 'working');
  C.model([1050, 600, 150, 300]);
});

const S208 = new Sys(2, 1, 13, 1, -3, -4);
const bad208 = r`2x - 6y = -4`, good208 = r`2x - 6y = -8`;
Q('s208', mk.short({ marks: 2, stem: J(r`Imran solves $2x + y = 13$ and $x - 3y = -4$. To eliminate $x$ he multiplies the second equation by $2$ and writes $2x - 6y = -4$. He then subtracts it from the first equation and gets $y = \dfrac{17}{7}$.`, 'Find his mistake and give the correct value of $y$.'), model: r`Imran multiplied the left side of $x - 3y = -4$ by $2$ but not the right side. The new equation should be $2x - 6y = -8$.

Subtracting from $2x + y = 13$: $7y = 13 + 8 = 21$, so $y = 3$.`, sol: 'Every term of the equation, including the constant, is multiplied.', scheme: [['Right-hand side -4 was not multiplied by 2 (should be -8)', 1], ['7y = 21, so y = 3', 1]], d: 3, c: 'analysis', t: [1], time: 120 }), (C) => {
  C.assert(fails(S208.env, bad208) && !fails(S208.env, good208), 'the slip is false at the solution, the correction is true');
  C.assert(S208.x.eq(F(5)) && S208.y.eq(F(3)) && !F(17, 7).eq(S208.y), 'solution (5, 3); the wrong y is not 3');
  C.assert(elimSteps(S208, 'x', 1).wv.eq(F(3)) && elimSteps(S208, 'x', 1).m2 === 2, 'correct elimination gives y = 3 with multiplier 2');
  C.model([8, 21, 3]);
});

// =============================================================== short answer, 3 marks
const S301 = sysFrom(5, 6, 7, 4, -3, 4);
const E301 = elimSteps(S301, 'y', 1);
Q('s301', mk.short({ marks: 3, stem: `Solve by elimination: ${both(S301)}. Check your answer in both equations.`, model: J('Eliminate $y$ (its coefficients $6$ and $4$ have LCM $12$).', stepsMd(E301.rows), `Check: $5(-3) + 6(4) = -15 + 24 = 9$ and $7(-3) + 4(4) = -21 + 16 = -5$.`), sol: 'Scale to equal y-coefficients, subtract, back-substitute and check.', scheme: [['Multipliers 2 and 3 with the scaled equations', 1], ['Subtracting: -11x = 33, so x = -3, then y = 4', 1], ['Check in both original equations', 1]], d: 3, c: 'application', t: [1], time: 210 }), (C) => {
  C.assert(E301.m1 === 2 && E301.m2 === 3 && E301.op === 'subtract' && E301.k === -11 && E301.rhs === 33 && S301.x.eq(F(-3)) && S301.y.eq(F(4)), 'multipliers 2, 3; -11x = 33');
  C.assert(W({}, [r`5(-3) + 6(4) = -15 + 24 = 9`, r`7(-3) + 4(4) = -21 + 16 = -5`]), 'check lines');
  C.model([2, 3, 11, 33, 3, 4]);
});

const S302 = new Sys(4, 7, 17, 2, -1, 4);
const U302 = substSteps(S302, 2, 'y');
Q('s302', mk.short({ marks: 3, stem: `Solve by substitution: ${both(S302)}.`, model: J(r`The second equation has a unit coefficient for $y$, so isolate $y$ there.`, stepsMd(U302.rows)), sol: 'Isolate y from the second equation, substitute into the first.', scheme: [['y = 2x - 4 from the second equation', 1], ['Substitute: 18x = 45, so x = 5/2', 1], ['y = 1', 1]], d: 3, c: 'application', t: [2], time: 180 }), (C) => {
  C.assert(S302.x.eq(F(5, 2)) && S302.y.eq(F(1)) && U302.K.eq(F(18)) && U302.C.eq(F(45)), '18x = 45; x = 5/2, y = 1');
  C.model([18, 45, 2, 4, 1]);
});

const S303 = sysFrom(6, 5, 4, -7, 4, -3);
const X303 = crossSteps(S303);
Q('s303', mk.short({ marks: 3, stem: `Using cross-multiplication, solve ${both(S303)}.`, model: J(r`Rewrite as $ax + by + c = 0$ (so $c_1 = -9$, $c_2 = -37$) and use $\dfrac{x}{b_1c_2 - b_2c_1} = \dfrac{y}{c_1a_2 - c_2a_1} = \dfrac{1}{a_1b_2 - a_2b_1}$.`, stepsMd(X303.rows)), sol: 'Standard form, three denominators, equate to 1 over the last.', scheme: [['Standard form with c1 = -9 and c2 = -37', 1], ['Denominators -248, 186 and -62', 1], ['x = 4 and y = -3', 1]], d: 3, c: 'application', t: [3], time: 210 }), (C) => {
  C.assert(X303.c1 === -9 && X303.c2 === -37 && S303.x.eq(F(4)) && S303.y.eq(F(-3)), 'constants; solution (4, -3)');
  C.model([X303.Dx, X303.Dy, X303.D, 4, 3].map((v) => Math.abs(v)));
});

const S304 = new Sys(4, 3, 48, 4, -1, 16);
const q304 = [r`\dfrac{x}{3} + \dfrac{y}{4} = 4`, r`\dfrac{x}{2} - \dfrac{y}{8} = 2`];
const E304 = elimSteps(S304, 'x', 1);
Q('s304', mk.short({ marks: 3, stem: `Solve ${d(q304[0])} and ${d(q304[1])}.`, model: J(r`Clear the fractions: multiply the first equation by $12$ and the second by $8$, giving $4x + 3y = 48$ and $4x - y = 16$.`, stepsMd(E304.rows)), sol: 'Clear the fractions first, then eliminate x (equal coefficients, subtract).', scheme: [['Cleared pair 4x + 3y = 48 and 4x - y = 16', 1], ['Subtracting: 4y = 32, so y = 8', 1], ['x = 6', 1]], d: 3, c: 'application', t: [1], time: 210 }), (C) => {
  C.assert(cleared(q304[0]).join() === '4,3,48' && cleared(q304[1]).join() === '4,-1,16', 'cleared forms');
  C.assert(S304.x.eq(F(6)) && S304.y.eq(F(8)) && W(S304.env, q304), 'original equations hold at (6, 8)');
  C.assert(E304.op === 'subtract' && E304.k === 4 && E304.rhs === 32, '4y = 32');
  C.model([12, 8, 48, 16, 32, 6]);
});

const R305 = recipSys(4, 3, 3, 2, -9, -2);
const E305 = elimSteps(R305.S, 'v', 1);
Q('s305', mk.short({ marks: 3, stem: r`Solve $\dfrac{4}{x} + \dfrac{3}{y} = 3$ and $\dfrac{2}{x} - \dfrac{9}{y} = -2$ for $x$ and $y$.`, model: J(r`Put $u = \dfrac{1}{x}$ and $v = \dfrac{1}{y}$: $4u + 3v = 3$ and $2u - 9v = -2$.`, stepsMd(E305.rows), r`So $u = \dfrac{1}{2}$ and $v = \dfrac{1}{3}$. Hence $x = \dfrac{1}{u} = 2$ and $y = \dfrac{1}{v} = 3$.`), sol: 'Reduce to a linear pair in u and v, solve, then take reciprocals.', scheme: [['4u + 3v = 3 and 2u - 9v = -2', 1], ['u = 1/2 and v = 1/3', 1], ['x = 2 and y = 3', 1]], d: 4, c: 'application', t: [1], time: 240 }), (C) => {
  C.assert(R305.S.x.eq(F(1, 2)) && R305.S.y.eq(F(1, 3)) && R305.x.eq(F(2)) && R305.y.eq(F(3)), 'u = 1/2, v = 1/3, x = 2, y = 3');
  C.assert(W(R305.env, [r`4u + 3v = 3`, r`2u - 9v = -2`, r`x = \dfrac{1}{u}`, r`y = \dfrac{1}{v}`]), 'working');
  C.model([4, 3, 2, 9, 2, 3]);
});

const S306 = new Sys(1, 1, 15, 1, -1, 9);
Q('s306', mk.short({ marks: 3, stem: r`A motor-boat goes $45$ km downstream in $3$ hours and comes back the same $45$ km upstream in $5$ hours. Find the speed of the boat in still water and the speed of the stream.`, model: r`Downstream speed $= \dfrac{45}{3} = 15$ km/h; upstream speed $= \dfrac{45}{5} = 9$ km/h.

Let the boat's speed be $u$ and the stream's $v$ (km/h). Then $u + v = 15$ and $u - v = 9$.

Adding, $2u = 24$, so $u = 12$; subtracting, $2v = 6$, so $v = 3$.

The boat's speed in still water is $12$ km/h and the stream flows at $3$ km/h.`, sol: 'Downstream speed is u + v, upstream speed is u - v.', scheme: [['Speeds 15 and 9 from distance over time', 1], ['u + v = 15 and u - v = 9', 1], ['u = 12 km/h and v = 3 km/h', 1]], d: 3, c: 'application', t: [4], time: 180 }), (C) => {
  C.assert(F(45).div(F(3)).eq(F(15)) && F(45).div(F(5)).eq(F(9)) && S306.x.eq(F(12)) && S306.y.eq(F(3)), 'speeds 15 and 9; u = 12, v = 3');
  C.assert(W({ u: 12, v: 3 }, [r`u + v = 15`, r`u - v = 9`, r`2u = 24`, r`2v = 6`]), 'working');
  C.model([15, 9, 24, 6, 12, 3]);
});

// =============================================================== long answer, 10 marks
// l01 the three methods
const S01a = sysFrom(9, -4, 5, 6, 2, 3), E01a = elimSteps(S01a, 'y', 1);
const S01b = sysFrom(1, 3, 3, -4, 5, 2), U01b = substSteps(S01b, 1, 'x');
const S01c = sysFrom(5, 2, 3, -4, 3, -2), X01c = crossSteps(S01c);
Q('l01', mk.long({ marks: 10, stem: J(`(a) Solve ${both(S01a)} by the elimination method. [3]`, `(b) Solve ${both(S01b)} by the substitution method. [3]`, `(c) Solve ${both(S01c)} by the cross-multiplication method. [4]`), model: J(`(a) ${stepsMd(E01a.rows).replace(/\n\n/g, '\n\n')}`, `(b) Isolate $x$ from the first equation (unit coefficient).`, stepsMd(U01b.rows), `(c) ${stepsMd(X01c.rows)}`), sol: 'One pair for each method; each answer is substituted back into both equations.', scheme: [['(a) Multipliers 3 and 2 and the scaled equations', 1], ['(a) Adding: 37x = 74, so x = 2', 1], ['(a) y = 3', 1], ['(b) x = 11 - 3y', 1], ['(b) Substituting: -13y = -26, so y = 2', 1], ['(b) x = 5', 1], ['(c) Standard form (c1 = -11, c2 = -17) and denominators -78, 52, -26', 1], ['(c) The scheme equated to 1 over the third denominator', 1], ['(c) x = 3', 1], ['(c) y = -2', 1]], d: 3, c: 'application', t: [1, 2, 3], time: 600 }), (C) => {
  C.assert(E01a.m1 === 3 && E01a.m2 === 2 && E01a.op === 'add' && E01a.k === 37 && E01a.rhs === 74 && S01a.x.eq(F(2)) && S01a.y.eq(F(3)), '(a) 37x = 74; (2, 3)');
  C.assert(U01b.K.eq(F(-13)) && U01b.C.eq(F(-26)) && S01b.x.eq(F(5)) && S01b.y.eq(F(2)), '(b) -13y = -26; (5, 2)');
  C.assert(X01c.c1 === -11 && X01c.c2 === -17 && S01c.x.eq(F(3)) && S01c.y.eq(F(-2)), '(c) c1, c2; (3, -2)');
  C.model([37, 74, 13, 26, 3, 2, X01c.Dx, X01c.D].map(Math.abs));
});

// l02 fractions to integer form, then solve and check
const q02 = [r`\dfrac{x}{2} + \dfrac{y}{3} = 5`, r`\dfrac{x - 1}{3} - \dfrac{y - 3}{2} = -2`];
const S02l = new Sys(3, 2, 30, 2, -3, -19), E02l = elimSteps(S02l, 'x', 1);
Q('l02', mk.long({ marks: 10, stem: J(`Consider the pair ${d(q02[0])} and ${d(q02[1])}.`, '(a) Clear the fractions and write each equation as $ax + by = c$. [3]', '(b) Solve the pair by elimination. [3]', r`(c) Check your values in both of the **original** equations, and find the value of $\dfrac{y}{x}$. [4]`), model: J(r`(a) Multiply the first equation by $6$: $3x + 2y = 30$.`, r`For the second, multiply by $6$: $2(x - 1) - 3(y - 3) = -12$, so $2x - 2 - 3y + 9 = -12$, that is $2x - 3y = -19$.`, `(b) ${stepsMd(E02l.rows)}`, r`(c) First equation: $\dfrac{4}{2} + \dfrac{9}{3} = 2 + 3 = 5$. Second equation: $\dfrac{4 - 1}{3} - \dfrac{9 - 3}{2} = 1 - 3 = -2$. Both hold.`, r`$\dfrac{y}{x} = \dfrac{9}{4}$.`), sol: 'Clear fractions, solve the integer pair, and verify in the original equations.', scheme: [['(a) 3x + 2y = 30', 1], ['(a) 2(x - 1) - 3(y - 3) = -12 expanded', 1], ['(a) 2x - 3y = -19', 1], ['(b) Multipliers 2 and 3 and the scaled equations', 1], ['(b) Subtracting: 13y = 117, so y = 9', 1], ['(b) x = 4', 1], ['(c) First original equation checked: 2 + 3 = 5', 1], ['(c) Second original equation checked: 1 - 3 = -2', 1], ['(c) y/x = 9/4', 2]], d: 4, c: 'application', t: [1], time: 600 }), (C) => {
  C.assert(cleared(q02[0]).join() === '3,2,30' && cleared(q02[1]).join() === '2,-3,-19', '(a) cleared forms');
  C.assert(S02l.x.eq(F(4)) && S02l.y.eq(F(9)) && W(S02l.env, q02) && E02l.k === 13 && E02l.rhs === 117, '(b), (c) original equations hold at (4, 9)');
  C.assert(S02l.y.div(S02l.x).eq(F(9, 4)), 'y/x = 9/4');
  C.model([30, 12, 19, 13, 117, 4, 9]);
});

// l03 reciprocal pair
const R03 = recipSys(6, 10, 5, 4, -5, 1), E03l = elimSteps(R03.S, 'v', 1);
Q('l03', mk.long({ marks: 10, stem: J(r`Consider $\dfrac{6}{x} + \dfrac{10}{y} = 5$ and $\dfrac{4}{x} - \dfrac{5}{y} = 1$.`, r`(a) Put $u = \dfrac{1}{x}$ and $v = \dfrac{1}{y}$ and write the pair as two linear equations in $u$ and $v$. [3]`, '(b) Solve them for $u$ and $v$. [3]', r`(c) Find $x$ and $y$, check them in the first original equation, and find $x + y$. [4]`), model: J(r`(a) Since $\dfrac{6}{x} = 6u$ and $\dfrac{10}{y} = 10v$, the first equation becomes $6u + 10v = 5$; similarly the second becomes $4u - 5v = 1$.`, `(b) ${stepsMd(E03l.rows)}`, r`(c) $x = \dfrac{1}{u} = 2$ and $y = \dfrac{1}{v} = 5$. Check: $\dfrac{6}{2} + \dfrac{10}{5} = 3 + 2 = 5$. So $x + y = 7$.`), sol: 'Substitute u and v, solve the linear pair, take reciprocals, verify.', scheme: [['(a) 6u + 10v = 5', 1], ['(a) 4u - 5v = 1', 1], ['(a) Reason: 6/x = 6u, 10/y = 10v', 1], ['(b) Multiplier 2 on the second equation, then adding: 14u = 7', 1], ['(b) u = 1/2', 1], ['(b) v = 1/5', 1], ['(c) x = 2 and y = 5 (reciprocals)', 2], ['(c) Check 3 + 2 = 5', 1], ['(c) x + y = 7', 1]], d: 4, c: 'application', t: [1], time: 600 }), (C) => {
  C.assert(R03.S.x.eq(F(1, 2)) && R03.S.y.eq(F(1, 5)) && R03.x.eq(F(2)) && R03.y.eq(F(5)), 'u = 1/2, v = 1/5, x = 2, y = 5');
  C.assert(W(R03.env, [r`6u + 10v = 5`, r`4u - 5v = 1`, r`\dfrac{6}{x} + \dfrac{10}{y} = 3 + 2 = 5`]), 'working');
  C.assert(E03l.m1 === 1 && E03l.m2 === 2 && E03l.k === 14 && E03l.rhs === 7, '14u = 7');
  C.model([6, 10, 4, 5, 14, 7, 2, 5]);
});

// l04 two-digit number
const S04l = new Sys(6, -3, 0, -1, 1, 3), E04l = elimSteps(new Sys(2, -1, 0, -1, 1, 3), 'y', 1);
Q('l04', mk.long({ marks: 10, stem: J(r`A two-digit number is $4$ times the sum of its digits. If $27$ is added to the number, the digits are interchanged.`, '(a) Taking the tens digit as $x$ and the units digit as $y$, form two equations. [3]', '(b) Solve them. [3]', '(c) Write down the number, verify both conditions, and find the number obtained by reversing the digits. [4]'), model: J(r`(a) The number is $10x + y$. First condition: $10x + y = 4(x + y)$, so $6x - 3y = 0$, that is $2x - y = 0$.`, r`Second condition: $10x + y + 27 = 10y + x$, so $9y - 9x = 27$, that is $y - x = 3$.`, `(b) ${stepsMd(E04l.rows)}`, r`(c) The number is $10(3) + 6 = 36$. The sum of the digits is $9$ and $4 \times 9 = 36$. Adding $27$ gives $63$, the digits interchanged. The reversed number is $63$.`), sol: 'Place value: 10x + y; reversed 10y + x.', scheme: [['(a) 10x + y = 4(x + y), simplified to 2x - y = 0', 1.5], ['(a) 10x + y + 27 = 10y + x, simplified to y - x = 3', 1.5], ['(b) Eliminating y by adding: x = 3', 2], ['(b) y = 6', 1], ['(c) Number 36, with 4 x 9 = 36 verified', 2], ['(c) 36 + 27 = 63, the reversed number', 2]], d: 4, c: 'application', t: [4], time: 600 }), (C) => {
  const fits = (n) => { const x = Math.floor(n / 10), y = n % 10; return n === 4 * (x + y) && n + 27 === y * 10 + x; };
  C.assert(S04l.x.eq(F(3)) && S04l.y.eq(F(6)) && fits(36), 'digits 3 and 6, number 36');
  C.assert([...Array(90).keys()].map((i) => i + 10).filter(fits).join() === '36', '36 is the only two-digit number satisfying both conditions');
  C.assert(W(S04l.env, [r`10x + y = 4(x + y)`, r`10x + y + 27 = 10y + x`, r`6x - 3y = 0`, r`9y - 9x = 27`]), 'equations');
  C.assert(E04l.k === 1 && E04l.rhs === 3 && E04l.op === 'add', 'adding gives x = 3');
  C.model([4, 27, 3, 6, 36, 63]);
});

// l05 ages
const S05l = new Sys(1, 1, 54, 1, -8, -63), E05l = elimSteps(S05l, 'x', 1);
Q('l05', mk.long({ marks: 10, stem: J(r`Nine years ago, Reena was $8$ times as old as her son. Four years from now, the sum of their ages will be $62$ years.`, '(a) Let their present ages be $x$ years (Reena) and $y$ years (her son). Form two equations. [3]', '(b) Solve them. [3]', '(c) State their present ages. After how many years from now will Reena be exactly $3$ times as old as her son? [4]'), model: J(r`(a) Nine years ago: $x - 9 = 8(y - 9)$, so $x - 8y = -63$.`, r`Four years from now: $(x + 4) + (y + 4) = 62$, so $x + y = 54$.`, `(b) ${stepsMd(E05l.rows)}`, r`(c) Reena is $41$ years old and her son $13$. After $t$ years: $41 + t = 3(13 + t)$, so $41 + t = 39 + 3t$ and $t = 1$. In $1$ year Reena will be $42$ and her son $14$, and $42 = 3 \times 14$.`), sol: 'Ages: translate each time reference carefully.', scheme: [['(a) x - 9 = 8(y - 9), simplified to x - 8y = -63', 1.5], ['(a) x + y + 8 = 62, simplified to x + y = 54', 1.5], ['(b) Subtracting: 9y = 117, so y = 13', 2], ['(b) x = 41', 1], ['(c) Ages 41 and 13, with the story checked', 1], ['(c) 41 + t = 3(13 + t), solved: t = 1', 2], ['(c) Verify 42 = 3 x 14', 1]], d: 4, c: 'application', t: [4], time: 600 }), (C) => {
  C.assert(S05l.x.eq(F(41)) && S05l.y.eq(F(13)) && 41 - 9 === 8 * (13 - 9) && 41 + 4 + 13 + 4 === 62, 'ages 41 and 13');
  C.assert(W(S05l.env, [r`x - 9 = 8(y - 9)`, r`x - 8y = -63`, r`x + y = 54`]), 'equations');
  C.assert(E05l.k === 9 && E05l.rhs === 117 && E05l.wv.eq(F(13)), '9y = 117 by elimination of x');
  C.assert(F(41).add(F(1)).eq(F(3).mul(F(13).add(F(1)))) && W({ t: 1 }, [r`41 + t = 3(13 + t)`, r`41 + t = 39 + 3t`]), 't = 1');
  C.model([63, 54, 117, 13, 41, 39, 1, 42, 14]);
});

// l06 boat in a stream
const S06l = new Sys(1, 1, 18, 1, -1, 10), E06l = elimSteps(S06l, 'y', 1);
Q('l06', mk.long({ marks: 10, stem: J(r`A motor-boat travels $36$ km downstream in $2$ hours and $30$ km upstream in $3$ hours.`, '(a) Find its downstream and upstream speeds, and form two equations in the boat\'s speed $u$ km/h in still water and the stream\'s speed $v$ km/h. [3]', '(b) Solve them. [3]', '(c) How long does the boat take to go $45$ km upstream and then $54$ km downstream? [4]'), model: J(r`(a) Downstream speed $= \dfrac{36}{2} = 18$ km/h and upstream speed $= \dfrac{30}{3} = 10$ km/h. The stream helps the boat downstream and slows it upstream, so $u + v = 18$ and $u - v = 10$.`, `(b) ${stepsMd(E06l.rows)}`, r`(c) The boat's speed is $u = 14$ km/h and the stream's is $v = 4$ km/h. Upstream speed is $10$ km/h, so $45$ km takes $\dfrac{45}{10} = 4.5$ hours. Downstream speed is $18$ km/h, so $54$ km takes $\dfrac{54}{18} = 3$ hours. The total time is $4.5 + 3 = 7.5$ hours.`), sol: 'Speed = distance / time; downstream u + v, upstream u - v.', scheme: [['(a) Speeds 18 and 10 km/h from distance over time', 1], ['(a) u + v = 18', 1], ['(a) u - v = 10', 1], ['(b) Adding: 2u = 28, so u = 14', 2], ['(b) v = 4', 1], ['(c) Upstream time 45/10 = 4.5 hours', 1.5], ['(c) Downstream time 54/18 = 3 hours', 1.5], ['(c) Total time 7.5 hours', 1]], d: 4, c: 'application', t: [4], time: 600 }), (C) => {
  C.assert(F(36).div(F(2)).eq(F(18)) && F(30).div(F(3)).eq(F(10)) && S06l.x.eq(F(14)) && S06l.y.eq(F(4)), 'speeds 18 and 10; u = 14, v = 4');
  C.assert(E06l.k === 2 && E06l.rhs === 28 && F(45).div(F(10)).add(F(54).div(F(18))).eq(F(15, 2)), '2u = 28; total time 15/2');
  C.assert(W({ u: 14, v: 4 }, [r`u + v = 18`, r`u - v = 10`, r`\dfrac{45}{u - v} + \dfrac{54}{u + v} = 4.5 + 3 = 7.5`]), 'working');
  C.model([36, 30, 18, 10, 28, 14, 4, 4.5, 3, 7.5]);
});

// l07 fencing cost
const S07l = new Sys(1, 1, 65, 1, -1, 5), E07l = elimSteps(S07l, 'y', 1);
Q('l07', mk.long({ marks: 10, stem: J(r`Fencing a rectangular plot with wire at ₹$20$ per metre costs ₹$2600$. The length of the plot is $5$ m more than its breadth.`, '(a) Find the perimeter, and form two equations in the length $l$ m and the breadth $b$ m. [3]', '(b) Solve them. [3]', '(c) Find the area of the plot, and the cost of levelling it at ₹$12$ per square metre. [4]'), model: J(r`(a) Length of wire $= \dfrac{2600}{20} = 130$ m, so the perimeter is $130$ m. Then $2(l + b) = 130$, that is $l + b = 65$, and $l - b = 5$.`, `(b) ${stepsMd(E07l.rows)}`, r`(c) The plot is $35$ m by $30$ m, so its area is $35 \times 30 = 1050$ m$^2$. Levelling costs $1050 \times 12 = 12600$, that is ₹$12600$.`), sol: 'Perimeter from cost over rate; area and cost follow.', scheme: [['(a) Perimeter 2600 / 20 = 130 m', 1], ['(a) l + b = 65', 1], ['(a) l - b = 5', 1], ['(b) Adding: 2l = 70, so l = 35', 2], ['(b) b = 30', 1], ['(c) Area 35 x 30 = 1050 square metres', 2], ['(c) Levelling cost 1050 x 12 = 12600 rupees', 2]], d: 3, c: 'application', t: [4], time: 600 }), (C) => {
  C.assert(F(2600).div(F(20)).eq(F(130)) && S07l.x.eq(F(35)) && S07l.y.eq(F(30)) && 2 * (35 + 30) === 130 && 35 - 30 === 5, 'perimeter 130; l = 35, b = 30');
  C.assert(E07l.k === 2 && E07l.rhs === 70 && 35 * 30 === 1050 && 1050 * 12 === 12600, '2l = 70; area 1050; cost 12600');
  C.assert(W(S07l.env, [r`x + y = 65`, r`x - y = 5`, r`2x = 70`]), 'working');
  C.model([2600, 20, 130, 65, 70, 35, 30, 1050, 12600]);
});
